local cable={}local net_cache={}function cable.receive(id,callback)if SERVER then cable.check_networked_string(id)end return net.Receive(id,function(length,sender)local c_len=net.ReadUInt(8)local c_tables=table.map(string.split(net.ReadString(),";"),function(v)return tonumber(v)end)local tables={}local args={}if c_tables then for k,v in ipairs(c_tables)do tables[v]=!!1 end end if c_len>0 then for i=1,c_len do if tables[i]then local value,err=sfs.decode(net.ReadData(net.ReadUInt(16)))if err then error("cable.receive - failed to decode value #"..i.." of \""..id.."\" ("..err..")\n")end args[i]=value else args[i]=net.ReadType()end end end if IsValid(sender)then callback(sender,unpack(args))else callback(unpack(args))end end)end local function write_sendable_args(...)local args={ ... }local length=0 local table_header=""local send={}local tables={}for k,v in ipairs(args)do length=length+1 if!istable(v)then table.insert(send,v!=nil&&v||!1)else local data,err=sfs.encode(v)if err then error("cable.send - failed to encode value #"..length.." ("..err..")\n")end table.insert(send,data)tables[length]=!!1 table_header=table_header..tostring(length)..";"end end net.WriteUInt(length,8)net.WriteString(table_header)for k,v in ipairs(send)do if tables[k]then net.WriteUInt(#v,16)net.WriteData(v,#v)else net.WriteType(v)end end end if SERVER then function cable.check_networked_string(id)if!net_cache[id]then net_cache[id]=util.AddNetworkString(id)return!1 end return!!1 end function cable.send(target,id,...)if isstring(target)then error("cable.send - bad argument #1 (must not be a string)\n")end if!cable.check_networked_string(id)then local args={ ... }timer.Simple(0.1,function()cable.send(target,id,unpack(args))end)return end if!istable(target)then if IsValid(target)then target={target}else target=player.GetAll()end end net.Start(id)write_sendable_args(...)net.Send(target)end else function cable.send(id,...)net.Start(id)write_sendable_args(...)net.SendToServer()end end return cable
